package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import java.util.*;
/** Bounded media index queried off the UI thread. */
public final class MusicLibraryActivity extends LeoActivity {
 private final ArrayList<String[]> tracks=new ArrayList<String[]>();private final ArrayList<String> artKeys=new ArrayList<String>();private final RowArtwork artwork=new RowArtwork(this);private String artworkTitle="";private ArrayList<String[]> activeRows=new ArrayList<String[]>();private int activeIndex;private boolean viewingPlaylists;
 protected void onCreate(Bundle b){super.onCreate(b);load();}
 private static String label(String v,String fallback){return v==null||v.isEmpty()||v.equals("<unknown>")?fallback:v;}
 private void load(){begin(L.t("Bibliotecă muzicală"));root.addView(text(L.t("Se citesc piesele…"),18));footer("","",L.t("Înapoi"));worker.execute(new Runnable(){public void run(){final ArrayList<String[]> result=new ArrayList<String[]>();try(Cursor c=getContentResolver().query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,new String[]{"_id","title","artist","album","_display_name","album_id"},null,null,"title COLLATE NOCASE ASC")){while(c!=null&&c.moveToNext()&&result.size()<500)result.add(new String[]{ContentUris.withAppendedId(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,c.getLong(0)).toString(),label(c.getString(1),c.getString(4)),label(c.getString(2),L.t("Artist necunoscut")),label(c.getString(3),L.t("Album necunoscut")),"content://media/external/audio/albumart/"+c.getLong(5)});}catch(RuntimeException denied){}try(Cursor c=getContentResolver().query(MediaStore.Files.getContentUri("external"),new String[]{"_id","_display_name"},"_display_name LIKE ?",new String[]{"%.wma"},"_display_name COLLATE NOCASE ASC")){while(c!=null&&c.moveToNext()&&result.size()<500){String uri=ContentUris.withAppendedId(MediaStore.Files.getContentUri("external"),c.getLong(0)).toString();boolean duplicate=false;for(String[] t:result)if(Uri.parse(t[0]).getLastPathSegment().equals(""+c.getLong(0)))duplicate=true;if(!duplicate)result.add(new String[]{uri,c.getString(1),L.t("Artist necunoscut"),L.t("Album necunoscut")});}}catch(RuntimeException denied){}ui(new Runnable(){public void run(){tracks.clear();tracks.addAll(result);home();}});}});}
 protected void onResume(){super.onResume();if(viewingPlaylists)playlists();}
 private void home(){viewingPlaylists=false;list(L.t("Muzică · ")+tracks.size()+L.t(" piese"),Arrays.asList(L.t("Toate piesele"),L.t("Artiști"),L.t("Albume"),L.t("Liste de redare"),L.t("Media curentă"),L.t("Reîncarcă biblioteca"),L.t("Favorite"),L.t("Caută T9 / text"),L.t("Reia ultima sesiune")),0,new Choice(){public void pick(int i){if(i==8){try{MusicResume.read(MusicLibraryActivity.this);startService(new Intent(MusicLibraryActivity.this,PlaybackService.class).setAction("resume"));startActivity(new Intent(MusicLibraryActivity.this,MediaActivity.class).putExtra("now",true));}catch(Exception e){notice(L.t("Nu există o sesiune locală salvată"));}}else if(i==0)rows(L.t("Toate piesele"),tracks);else if(i==1||i==2)groups(i==1?2:3);else if(i==3)playlists();else if(i==6){ArrayList<String[]> fav=new ArrayList<String[]>();Set<String> ids=favorites();for(String[] t:tracks)if(ids.contains(t[0]))fav.add(t);rows(L.t("Piese favorite"),fav);}else if(i==7)search();else if(i==4)startActivity(new Intent(MusicLibraryActivity.this,NowPlayingActivity.class));else load();}},"Player",new Runnable(){public void run(){startActivity(new Intent(MusicLibraryActivity.this,MediaActivity.class).putExtra("now",true));}});}
 private void groups(final int column){viewingPlaylists=false;final TreeMap<String,ArrayList<String[]>> grouped=new TreeMap<String,ArrayList<String[]>>(String.CASE_INSENSITIVE_ORDER);for(String[] t:tracks){String key=column==3?t[3]+" · "+t[2]:t[column];if(!grouped.containsKey(key))grouped.put(key,new ArrayList<String[]>());grouped.get(key).add(t);}final ArrayList<String> keys=new ArrayList<String>(grouped.keySet()),labels=new ArrayList<String>();artKeys.clear();artworkTitle=column==2?L.t("Artiști Leo"):L.t("Albume Leo");for(String key:keys){labels.add(key+" · "+grouped.get(key).size());String[] t=grouped.get(key).get(0);artKeys.add(t.length>4?t[4]:"");}list(artworkTitle,labels,0,new Choice(){public void pick(int i){rows(keys.get(i),grouped.get(keys.get(i)));}},"",null);back=new Runnable(){public void run(){home();}};}
 private void rows(String title,final List<String[]> source){viewingPlaylists=false;final ArrayList<String[]> snapshot=new ArrayList<String[]>(source);int focus=title.equals(artworkTitle)?activeIndex:0;activeRows=snapshot;activeIndex=Math.min(focus,Math.max(0,snapshot.size()-1));artworkTitle=title;artKeys.clear();for(String[] t:snapshot)artKeys.add(t.length>4?t[4]:"");ArrayList<String> names=new ArrayList<String>();for(String[] t:snapshot)names.add((favorites().contains(t[0])?"★ ":"")+t[1]+(t.length>2?"\n"+t[2]:""));list(title,names,activeIndex,new Choice(){public void pick(int i){ArrayList<String> uris=new ArrayList<String>(),titles=new ArrayList<String>();for(String[] t:snapshot){uris.add(t[0]);titles.add(t[1]);}startService(new Intent(MusicLibraryActivity.this,PlaybackService.class).putStringArrayListExtra("queue",uris).putStringArrayListExtra("titles",titles).putExtra("index",i));startActivity(new Intent(MusicLibraryActivity.this,MediaActivity.class).putExtra("now",true));}},L.t("Opțiuni"),new Runnable(){public void run(){options(L.t("Piese"),new String[]{L.t("Adaugă / elimină favoritul"),L.t("Liste de redare"),L.t("Caută T9 / text")},new Choice(){public void pick(int i){if(i==1)playlists();else if(i==2)search();else if(!snapshot.isEmpty()){Set<String> ids=new HashSet<String>(favorites());String uri=snapshot.get(Math.min(activeIndex,snapshot.size()-1))[0];if(!ids.remove(uri))ids.add(uri);getSharedPreferences("music-library",0).edit().putStringSet("favorites",ids).apply();rows(artworkTitle,snapshot);}}});}});back=new Runnable(){public void run(){home();}};}
 private Set<String> favorites(){return getSharedPreferences("music-library",0).getStringSet("favorites",Collections.<String>emptySet());}
 private void search(){android.widget.LinearLayout f=fields(L.t("Caută muzică"));final android.widget.EditText q=field(f,L.t("Titlu, artist, album sau cifre T9"),"",android.text.InputType.TYPE_CLASS_TEXT);left=new Runnable(){public void run(){String term=q.getText().toString().trim();ArrayList<String[]> found=new ArrayList<String[]>();for(String[] t:tracks)if(GlobalSearchActivity.matches(t[1]+" "+t[2]+" "+t[3],term))found.add(t);rows(L.t("Rezultate muzică"),found);}};back=new Runnable(){public void run(){home();}};footer(L.t("Caută"),"Editor",L.t("Șterge"));q.requestFocus();}
 android.graphics.drawable.Drawable rowIcon(String title,int at){if(title.equals(L.t("Liste de redare"))){ArrayList<String> keys=new ArrayList<String>(MusicLists.read(this).keySet());if(at>=0&&at<keys.size()){String file=getSharedPreferences("playlist-art",0).getString(keys.get(at),"");if(file.matches("cover-[A-Za-z0-9_-]+\\.jpg")){java.io.File f=new java.io.File(getFilesDir(),"playlist-covers/"+file);return artwork.get(f.getPath(),Uri.fromFile(f),"♫");}}}if(!title.equals(artworkTitle)||at<0||at>=artKeys.size())return null;String uri=artKeys.get(at);return artwork.get(uri.isEmpty()?title+at:uri,uri.isEmpty()?null:Uri.parse(uri),"♫");}
 void onListSelection(String title,int at){if(title.equals(artworkTitle))activeIndex=at;}
 private void playlists(){viewingPlaylists=true;final TreeMap<String,ArrayList<String[]>> lists=MusicLists.read(this);final ArrayList<String> names=new ArrayList<String>(lists.keySet());list(L.t("Liste de redare"),names,0,new Choice(){public void pick(final int i){options(names.get(i),new String[]{L.t("Deschide"),L.t("Șterge lista · păstrează fișierele"),L.t("Editează lista și coperta")},new Choice(){public void pick(int action){if(action==2)startActivity(new Intent(MusicLibraryActivity.this,PlaylistEditorActivity.class).putExtra("name",names.get(i)));else if(action==0)rows(names.get(i),lists.get(names.get(i)));else options(L.t("Ștergi lista?"),new String[]{L.t("Păstrează"),L.t("Șterge lista")},new Choice(){public void pick(int yes){if(yes==1){lists.remove(names.get(i));MusicLists.write(MusicLibraryActivity.this,lists);playlists();}}});}});}},L.t("Salvează coada"),new Runnable(){public void run(){MusicLists.saveQueue(MusicLibraryActivity.this);}});back=new Runnable(){public void run(){home();}};}
}
